create extension if not exists pgcrypto;
do $$ begin create type public.memorial_visibility as enum ('public','unlisted','private'); exception when duplicate_object then null; end $$;
do $$ begin create type public.memorial_status as enum ('draft','pending_review','published','rejected','archived','removed'); exception when duplicate_object then null; end $$;
do $$ begin create type public.memorial_management_type as enum ('crowrules','family','community','organization'); exception when duplicate_object then null; end $$;
do $$ begin create type public.memorial_member_role as enum ('owner','manager','contributor','viewer'); exception when duplicate_object then null; end $$;
create table public.memorial_families(id uuid primary key default gen_random_uuid(),name text not null,created_by uuid not null references auth.users(id),created_at timestamptz default now());
create table public.memorial_family_members(family_id uuid references public.memorial_families(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role public.memorial_member_role not null default 'viewer',status text not null default 'active' check(status in ('invited','active','revoked')),primary key(family_id,user_id));
create table public.memorial_organizations(id uuid primary key default gen_random_uuid(),name text not null,description text,verification_status text not null default 'unverified',created_by uuid not null references auth.users(id),created_at timestamptz default now());
create table public.memorial_organization_members(organization_id uuid references public.memorial_organizations(id) on delete cascade,user_id uuid references auth.users(id) on delete cascade,role public.memorial_member_role not null default 'viewer',status text not null default 'active',primary key(organization_id,user_id));
create table public.memorial_profiles(id uuid primary key default gen_random_uuid(),slug text unique not null,display_name text not null,memorial_type text not null check(memorial_type in ('family','friend','public_figure','historical_figure','community_member','organization_collection')),birth_date date,passing_date date,biography text,portrait_path text,visibility public.memorial_visibility not null default 'private',status public.memorial_status not null default 'pending_review',management_type public.memorial_management_type not null default 'family',created_by uuid not null references auth.users(id),family_id uuid references public.memorial_families(id),organization_id uuid references public.memorial_organizations(id),family_stewardship_status text not null default 'not_requested',family_approval_status text not null default 'unknown',source_references jsonb not null default '[]',historical_review_status text not null default 'not_reviewed',approved_at timestamptz,created_at timestamptz default now(),updated_at timestamptz default now(),check(passing_date is null or birth_date is null or passing_date>=birth_date));
create index memorial_profiles_public_idx on public.memorial_profiles(status,visibility,display_name);
create table public.memorial_wings(id text primary key,name text not null,description text,is_active boolean default true);
create table public.memorial_profile_wings(memorial_id uuid references public.memorial_profiles(id) on delete cascade,wing_id text references public.memorial_wings(id),primary key(memorial_id,wing_id));
insert into public.memorial_wings(id,name) values ('hall','Hall of Remembrance'),('candlelight','Candlelight Sanctuary'),('portraits','Portrait Gallery'),('garden','Garden of Memories'),('horizons','Eternal Horizons'),('legacy','Legacy Library'),('celebration','Celebration of Life'),('community','Community Remembrance'),('museum','Memory Museum'),('walk','Remembrance Walk'),('constellation','Constellation of Lives'),('tree','Tree of Remembrance'),('voices','Voices That Remain'),('ravens-archive','The Raven''s Archive'),('memory-book','Memory Book'),('253','253 Remembrance Project') on conflict do nothing;
create table public.memorial_stories(id uuid primary key default gen_random_uuid(),memorial_id uuid references public.memorial_profiles(id) on delete cascade,author_id uuid references auth.users(id),title text,body text not null,visibility public.memorial_visibility default 'public',status text default 'pending',created_at timestamptz default now());
create table public.memorial_media(id uuid primary key default gen_random_uuid(),memorial_id uuid references public.memorial_profiles(id) on delete cascade,uploaded_by uuid references auth.users(id),storage_path text not null,media_type text not null,caption text,rights_attestation boolean default false,visibility public.memorial_visibility default 'private',status text default 'pending',created_at timestamptz default now());
create table public.memorial_tributes(id uuid primary key default gen_random_uuid(),memorial_id uuid references public.memorial_profiles(id) on delete cascade,author_id uuid references auth.users(id),message text not null check(char_length(message)<=3000),status text default 'pending',created_at timestamptz default now());
create table public.memorial_candles(id uuid primary key default gen_random_uuid(),memorial_id uuid references public.memorial_profiles(id) on delete cascade,created_by uuid references auth.users(id),dedication text,candle_style text default 'classic',is_sanctuary boolean default false,visibility public.memorial_visibility default 'public',created_at timestamptz default now(),check((is_sanctuary and memorial_id is null) or (not is_sanctuary and memorial_id is not null)));
create table public.memorial_submissions(id uuid primary key default gen_random_uuid(),memorial_id uuid references public.memorial_profiles(id),submitted_by uuid references auth.users(id),submission_type text not null,review_status text default 'pending',reviewer_id uuid references auth.users(id),reviewer_notes text,created_at timestamptz default now());
create table public.memorial_stewardship_requests(id uuid primary key default gen_random_uuid(),memorial_id uuid references public.memorial_profiles(id),requester_id uuid references auth.users(id),relationship_claim text not null,status text default 'pending',reviewer_id uuid references auth.users(id),created_at timestamptz default now());
create table public.memorial_reports(id uuid primary key default gen_random_uuid(),memorial_id uuid references public.memorial_profiles(id),reporter_id uuid references auth.users(id),reason text not null,details text,status text default 'open',created_at timestamptz default now());
create table public.memorial_audit_logs(id uuid primary key default gen_random_uuid(),actor_id uuid references auth.users(id),action text not null,target_type text not null,target_id uuid,reason text,metadata jsonb default '{}',created_at timestamptz default now());
create or replace function public.memorial_is_family_member(fid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.memorial_family_members m where m.family_id=fid and m.user_id=auth.uid() and m.status='active'); $$;
create or replace function public.memorial_is_org_member(oid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.memorial_organization_members m where m.organization_id=oid and m.user_id=auth.uid() and m.status='active'); $$;
create or replace function public.memorial_can_manage(mid uuid) returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.memorial_profiles p where p.id=mid and (p.created_by=auth.uid() or (p.family_id is not null and public.memorial_is_family_member(p.family_id)) or (p.organization_id is not null and public.memorial_is_org_member(p.organization_id)))); $$;
alter table public.memorial_profiles enable row level security; alter table public.memorial_families enable row level security; alter table public.memorial_family_members enable row level security; alter table public.memorial_organizations enable row level security; alter table public.memorial_organization_members enable row level security; alter table public.memorial_wings enable row level security; alter table public.memorial_profile_wings enable row level security; alter table public.memorial_stories enable row level security; alter table public.memorial_media enable row level security; alter table public.memorial_tributes enable row level security; alter table public.memorial_candles enable row level security; alter table public.memorial_submissions enable row level security; alter table public.memorial_stewardship_requests enable row level security; alter table public.memorial_reports enable row level security; alter table public.memorial_audit_logs enable row level security;
create policy "published public memorials" on public.memorial_profiles for select to anon,authenticated using(status='published' and visibility='public');
create policy "managed memorials" on public.memorial_profiles for select to authenticated using(created_by=auth.uid() or (family_id is not null and public.memorial_is_family_member(family_id)) or (organization_id is not null and public.memorial_is_org_member(organization_id)));
create policy "create own pending memorial" on public.memorial_profiles for insert to authenticated with check(created_by=auth.uid() and status in ('draft','pending_review'));
create policy "manager updates memorial" on public.memorial_profiles for update to authenticated using(public.memorial_can_manage(id)) with check(public.memorial_can_manage(id));
create policy "active wings readable" on public.memorial_wings for select to anon,authenticated using(is_active);
create policy "public wing links" on public.memorial_profile_wings for select to anon,authenticated using(exists(select 1 from public.memorial_profiles p where p.id=memorial_id and p.status='published' and p.visibility='public'));
create policy "manager wing links" on public.memorial_profile_wings for all to authenticated using(public.memorial_can_manage(memorial_id)) with check(public.memorial_can_manage(memorial_id));
create policy "public approved stories" on public.memorial_stories for select to anon,authenticated using(status='approved' and visibility='public' and exists(select 1 from public.memorial_profiles p where p.id=memorial_id and p.status='published' and p.visibility='public'));
create policy "manager stories" on public.memorial_stories for all to authenticated using(public.memorial_can_manage(memorial_id)) with check(public.memorial_can_manage(memorial_id));
create policy "public approved media metadata" on public.memorial_media for select to anon,authenticated using(status='approved' and visibility='public' and exists(select 1 from public.memorial_profiles p where p.id=memorial_id and p.status='published' and p.visibility='public'));
create policy "manager media" on public.memorial_media for all to authenticated using(public.memorial_can_manage(memorial_id)) with check(public.memorial_can_manage(memorial_id));
create policy "public approved tributes" on public.memorial_tributes for select to anon,authenticated using(status='approved' and exists(select 1 from public.memorial_profiles p where p.id=memorial_id and p.status='published' and p.visibility='public'));
create policy "manager tributes" on public.memorial_tributes for all to authenticated using(public.memorial_can_manage(memorial_id)) with check(public.memorial_can_manage(memorial_id));
create policy "public candles" on public.memorial_candles for select to anon,authenticated using(visibility='public' and (is_sanctuary or exists(select 1 from public.memorial_profiles p where p.id=memorial_id and p.status='published' and p.visibility='public')));
create policy "users create own candles" on public.memorial_candles for insert to authenticated with check(created_by=auth.uid());
create policy "own submissions" on public.memorial_submissions for select to authenticated using(submitted_by=auth.uid());
create policy "create own submissions" on public.memorial_submissions for insert to authenticated with check(submitted_by=auth.uid());
create policy "own stewardship requests" on public.memorial_stewardship_requests for select to authenticated using(requester_id=auth.uid());
create policy "create stewardship requests" on public.memorial_stewardship_requests for insert to authenticated with check(requester_id=auth.uid());
create policy "create reports" on public.memorial_reports for insert to authenticated with check(reporter_id=auth.uid());
create policy "own reports" on public.memorial_reports for select to authenticated using(reporter_id=auth.uid());
create policy "family membership self read" on public.memorial_family_members for select to authenticated using(user_id=auth.uid());
create policy "family creator or member read" on public.memorial_families for select to authenticated using(created_by=auth.uid() or public.memorial_is_family_member(id));
create policy "family create" on public.memorial_families for insert to authenticated with check(created_by=auth.uid());
create policy "org creator or member read" on public.memorial_organizations for select to authenticated using(created_by=auth.uid() or public.memorial_is_org_member(id));
create policy "org create" on public.memorial_organizations for insert to authenticated with check(created_by=auth.uid());
create policy "organization membership self read" on public.memorial_organization_members for select to authenticated using(user_id=auth.uid());
-- Membership changes, approval, audit writes and privileged actions belong in reviewed Edge Functions.
